local function recover()
  local rolling = SEED
  local P = {}
  for i = 1, #ENC do
    local e = ENC[i]
    local w = B.bxor(e, rolling)
    P[i] = w
    rolling = _xs(B.bxor(B.bxor(rolling, e), mul32(i - 1, 0x9E3779B1)))
  end
  for i = 1, #ENC do ENC[i] = 0 end
  return P
end
local function check_segs(P)
  if #P < #SEGS * 8 - 7 then return false end
  for s = 1, #SEGS do
    local a = (s - 1) * 8 + 1
    local b = math.min(a + 7, #P)
    local slice = {}
    for i = a, b do slice[#slice + 1] = P[i] end
    if B.bxor(fnv(slice), SEGS[s]) ~= 0 then return false end
    if B.bxor(djb(slice), SEGS2[s]) ~= 0 then return false end
  end
  return true
end
local function key_at(idx)
  return B.bxor(B.bxor(mul32(CONST, idx + 1), SEED), mul32(idx, 0x9E37))
end
local function dec_word(w, idx)
  local v = B.bxor(w, key_at(idx))
  local raw = B.rshift(v, 24) % 256
  local a = B.rshift(v, 16) % 256
  local b = B.rshift(v, 8) % 256
  local c = v % 256
  local real = INV[raw + 1]
  return real, a, b, c
end
local pieces = {}
local decoded = nil
local cus = _cus()
local function h_load(idx)
  if not C[idx + 1] then return true end
  local raw = b64dec(C[idx + 1], cus)
  if not raw or #raw < 4 then return false end
  local mac = string.byte(raw, 1) + string.byte(raw, 2) * 256 + string.byte(raw, 3) * 65536 + string.byte(raw, 4) * 16777216
  local body = raw:sub(5)
  local kb = ks_bytes(SEED, #body, idx * 0x100)
  local t = {}
  for i = 1, #body do
    local by = B.bxor(string.byte(body, i), kb[i])
    by = B.bxor(by, sb_byte((i - 1) % 256))
    t[i] = string.char(by)
  end
  local pt = table.concat(t)
  local m2 = 0
  for i = 1, #pt do m2 = (m2 * 131 + string.byte(pt, i)) % 4294967296 end
  if m2 ~= mac then return false end
  pieces[idx + 1] = pt
  C[idx + 1] = ""
  return true
end
local function h_cat()
  decoded = table.concat(pieces)
  for i = 1, #pieces do pieces[i] = "" end
end
local function h_exec()
  if not decoded or #decoded == 0 then return decoy() end
  local ls = loadstring or load
  if not ls then return decoy() end
  local fn = ls(decoded)
  decoded = ""
  if not fn then return decoy() end
  return fn()
end
local function run_vm(P)
