  for i = 0, 15 do R[i] = 0 end
  local pc = 1
  local guard = 0
  local depth = 0
  while pc >= 1 and pc <= #P and guard < 400000 do
    guard = guard + 1
    if depth > 32 then return decoy() end
    local op, a, b, c = dec_word(P[pc], pc - 1)
